const caeRecibido = $('Factura').first().json.factura.CAE.numero;
const elasticResults = $('Get many documents_old').all();

// Buscar si existe el CAE en los resultados
const documentoEncontrado = elasticResults.find(item => 
  item?.json?.CAE?.numero == caeRecibido
);

const id = documentoEncontrado ? documentoEncontrado.json.CAE.numero : null;

return [
  {
    json: {
      resultados: id
    }
  }
];

const factura = $('Factura').first().json.factura;
const items = factura.items;
const totales = factura.totales;

// 🧾 Tabla de ítems
let tablaItems = `
<p><strong>Conceptos facturados:</strong></p>
<table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; width: 100%; text-align: left; margin-top: 10px;">
  <thead>
    <tr style="background-color:#f0f0f0;">
      <th>Código</th>
      <th>Descripción</th>
      <th>Cantidad</th>
      <th>Unidad</th>
      <th>Precio Unitario</th>
      <th>Subtotal</th>
      <th>IVA</th>
      <th>Subtotal c/IVA</th>
    </tr>
  </thead>
  <tbody>
`;

for (const item of items) {
  tablaItems += `
    <tr>
      <td>${item.codigo}</td>
      <td>${item.descripcion}</td>
      <td>${item.cantidad}</td>
      <td>${item.unidad_medida}</td>
      <td>$ ${item.precio_unitario.toLocaleString('es-AR')}</td>
      <td>$ ${item.subtotal.toLocaleString('es-AR')}</td>
      <td>${item.alicuota_IVA || ""}%</td>
      <td>$ ${item.subtotal_c_IVA ? item.subtotal_c_IVA.toLocaleString('es-AR') : ""}</td>
    </tr>
  `;
}

tablaItems += `
  </tbody>
</table>
`;

// 💰 Detalle de impuestos (simplificado)
// const totalIVA =
//   (totales.IVA.t_27 || 0) +
//   (totales.IVA.t_21 || 0) +
//   (totales.IVA.t_105 || 0) +
//   (totales.IVA.t_5 || 0) +
//   (totales.IVA.t_205 || 0) +
//   (totales.IVA.t_0 || 0);

let detalleImpuestos = `
<p><strong>Detalle de importes:</strong></p>
<table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; width: 50%; text-align: left; margin-top: 10px;">
  <thead>
    <tr style="background-color:#f0f0f0;">
      <th>Concepto</th>
      <th>Importe</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td>Importe Neto Gravado</td>
      <td>$ ${ totales.importe_neto_gravado ? totales.importe_neto_gravado.toLocaleString('es-AR') : ""}</td>
    </tr>
    <tr>
      <td>IVA Total</td>
      <td>$ ${ /*factura.tipo == "A" ? totalIVA.toLocaleString('es-AR') : */ "" }</td>
    </tr>
    <tr>
      <td>Otros Tributos</td>
      <td>$ ${totales.importe_otros_tributos.toLocaleString('es-AR')}</td>
    </tr>
    <tr style="font-weight:bold; background-color:#f9f9f9;">
      <td>Total Factura</td>
      <td>$ ${totales.importe_total.toLocaleString('es-AR')}</td>
    </tr>
  </tbody>
</table>
`;

// 🗓️ Fecha de emisión
const fechaEmision = `<p><strong>Fecha de emisión:</strong> ${factura.fecha_emision}</p>`;

// 📦 Resultado combinado
const cuerpoMail = `
${fechaEmision}
${tablaItems}
${detalleImpuestos}
`;

return [
  {
    json: {
      cuerpo_mail: cuerpoMail,
      tabla_items: tablaItems,
      detalle_impuestos: detalleImpuestos,
      fecha_emision: factura.fecha_emision
    }
  }
];

