const items = $input.all();
const output = [];

for (const item of items) {
  // Si ya tiene binary.data, lo pasamos directamente
  if (item.binary && item.binary.data) {
    const binaryData = item.binary.data;
    const newFileName = binaryData.fileName ? binaryData.fileName.replace(/\s+/g, '_') : binaryData.fileName;

    output.push({
      json: item.json,
      binary: { 
        data: {
          ...binaryData,
          fileName: newFileName
        }
      },
    });
  }
  // Si tiene otros campos binarios, iteramos
  else if (item.binary) {
    for (const [key, value] of Object.entries(item.binary)) {
      const name = value.fileName || "";
      if (name.toLowerCase().endsWith(".pdf")) {
        const newFileName = name.replace(/\s+/g, '_');

        output.push({
          json: item.json,
          binary: { 
            data: {
              ...value,
              fileName: newFileName
            }
          },
        });
      }
    }
  }
}

return output;

